// Find free time slots within a day given a list of busy ranges.
const { parseTime, parseRange, formatMinutes } = require("./time-range");

function freeSlots(busy, dayStart, dayEnd, minLen = 0) {
  if (!Array.isArray(busy)) throw new Error("busy must be an array");
  const start = parseTime(dayStart);
  const end = parseTime(dayEnd);
  if (end <= start) throw new Error("dayEnd must be after dayStart");
  if (typeof minLen !== "number" || Number.isNaN(minLen) || minLen < 0) {
    throw new Error("bad minLen: " + minLen);
  }

  const clipped = [];
  for (const item of busy) {
    const r = parseRange(item);
    const s = Math.max(r.start, start);
    const e = Math.min(r.end, end);
    if (s < e) clipped.push({ start: s, end: e });
  }

  clipped.sort((a, b) => a.start - b.start || a.end - b.end);

  const merged = [];
  for (const r of clipped) {
    if (merged.length === 0 || r.start > merged[merged.length - 1].end) {
      merged.push({ start: r.start, end: r.end });
    } else if (r.end > merged[merged.length - 1].end) {
      merged[merged.length - 1].end = r.end;
    }
  }

  const slots = [];
  let cursor = start;
  for (const r of merged) {
    if (r.start > cursor && r.start - cursor >= minLen) {
      slots.push(`${formatMinutes(cursor)}-${formatMinutes(r.start)}`);
    }
    cursor = r.end;
  }
  if (end > cursor && end - cursor >= minLen) {
    slots.push(`${formatMinutes(cursor)}-${formatMinutes(end)}`);
  }

  return slots;
}

module.exports = { freeSlots };
