const assert = require("node:assert");
const { parseTime, parseRange, formatMinutes } = require("./time-range");
const { freeSlots } = require("./free-slots");
const pkg = require("./index");

// index.js re-exports everything.
assert.strictEqual(pkg.parseTime, parseTime);
assert.strictEqual(pkg.parseRange, parseRange);
assert.strictEqual(pkg.formatMinutes, formatMinutes);
assert.strictEqual(pkg.freeSlots, freeSlots);

// formatMinutes formatting and validation.
assert.strictEqual(formatMinutes(0), "00:00");
assert.strictEqual(formatMinutes(5), "00:05");
assert.strictEqual(formatMinutes(65), "01:05");
assert.strictEqual(formatMinutes(600), "10:00");
assert.strictEqual(formatMinutes(1439), "23:59");
assert.strictEqual(formatMinutes(parseTime("08:09")), "08:09");
assert.throws(() => formatMinutes(-1));
assert.throws(() => formatMinutes(1440));
assert.throws(() => formatMinutes(1.5));
assert.throws(() => formatMinutes(NaN));

// Unsorted, overlapping, and nested busy ranges (and input is not mutated).
const overlapping = ["13:00-14:30", "10:00-11:30", "11:00-12:00", "10:30-11:00"];
const snapshot = [...overlapping];
assert.deepStrictEqual(
  freeSlots(overlapping, "09:00", "17:00", 30),
  ["09:00-10:00", "12:00-13:00", "14:30-17:00"]
);
assert.deepStrictEqual(overlapping, snapshot);

// Duplicate and fully nested ranges.
assert.deepStrictEqual(
  freeSlots(["10:00-12:00", "10:00-12:00", "10:15-11:45"], "09:00", "13:00", 30),
  ["09:00-10:00", "12:00-13:00"]
);

// Touching ranges leave no zero-length gaps even when minLen is 0.
assert.deepStrictEqual(
  freeSlots(["12:30-14:00", "10:00-11:00", "11:00-12:30"], "09:00", "16:00", 0),
  ["09:00-10:00", "14:00-16:00"]
);
assert.deepStrictEqual(
  freeSlots(["09:00-12:00", "12:00-17:00"], "09:00", "17:00", 0),
  []
);

// minLen boundary: gaps of 30, 29, 31, and 30 minutes.
const boundaryBusy = ["09:30-10:00", "10:29-11:00", "11:31-16:30"];
assert.deepStrictEqual(
  freeSlots(boundaryBusy, "09:00", "17:00", 30),
  ["09:00-09:30", "11:00-11:31", "16:30-17:00"]
);
assert.deepStrictEqual(
  freeSlots(boundaryBusy, "09:00", "17:00", 31),
  ["11:00-11:31"]
);
assert.deepStrictEqual(
  freeSlots(boundaryBusy, "09:00", "17:00", 32),
  []
);

// Busy ranges outside the day, touching day edges, and straddling day bounds.
assert.deepStrictEqual(
  freeSlots(
    [
      "06:00-07:30",
      "07:30-09:00",
      "08:30-10:00",
      "16:00-18:30",
      "17:00-18:00",
      "19:00-21:00"
    ],
    "09:00",
    "17:00",
    30
  ),
  ["10:00-16:00"]
);
assert.deepStrictEqual(
  freeSlots(["05:00-09:00", "17:00-22:00"], "09:00", "17:00", 60),
  ["09:00-17:00"]
);
assert.deepStrictEqual(
  freeSlots(["07:00-20:00"], "09:00", "17:00", 1),
  []
);

// Empty busy list.
assert.deepStrictEqual(freeSlots([], "09:00", "17:00", 60), ["09:00-17:00"]);
assert.deepStrictEqual(freeSlots([], "09:00", "09:30", 60), []);

// Error cases: invalid day bounds and bad strings via parseTime/parseRange.
assert.throws(() => freeSlots([], "09:00", "09:00", 15));
assert.throws(() => freeSlots([], "17:00", "09:00", 15));
assert.throws(() => freeSlots([], "25:00", "17:00", 15), /bad time/);
assert.throws(() => freeSlots([], "09:00", "9:00", 15), /bad time/);
assert.throws(() => freeSlots(["bad"], "09:00", "17:00", 15), /bad range/);
assert.throws(() => freeSlots(["08:00-07:00"], "09:00", "17:00", 15), /range ends before it starts/);
assert.throws(() => freeSlots(["24:00-25:00"], "09:00", "17:00", 15), /bad time/);
